func:
// Apenas marca o estado interno. O ST do XP325 faz a sequencia sozinho.
var state = flow.get('tsea_state') || {};
state.ciclo_ativo = true;
state.finalizado = false;
state.emergencia_ativa = false;
state.etapa_atual = 10;
state.codigo_alarme = 0;
state.last_cycle_at = new Date().toISOString();
flow.set('tsea_state', state);

msg.payload = {
    ok: true,
    forwarded: true,
    mode: 'bancada_iot_senai',
    operation_id: msg.payload && msg.payload.operation_id ? msg.payload.operation_id : null,
    sequence: [
        { etapa: 10, duration_s: 5, motor: 'Motor 1 (Bomba B1)' },
        { etapa: 20, duration_s: 5, motor: 'Motor 2 (Bomba B2)' },
        { etapa: 30, duration_s: 5, motor: 'Motor 3 (Sistema de Oleo)' },
        { etapa: 40, duration_s: 0, motor: 'FINALIZADO' }
    ],
    timestamp: new Date().toISOString()
};
return msg;

var state = flow.get('tsea_state') || {};
state.ciclo_ativo = false;
state.finalizado = false;
state.emergencia_ativa = true;
state.etapa_atual = -1;
state.codigo_alarme = 1;
state.last_emergency_at = new Date().toISOString();
flow.set('tsea_state', state);

msg.payload = {
    ok: true,
    forwarded: true,
    mode: 'emergency',
    actions: [
        'Motor 1 OFF (Q0.0)',
        'Motor 2 OFF (Q0.1)',
        'Motor 3 OFF (Q0.2)',
        'Farol vermelho ON (Q0.5)'
    ],
    timestamp: new Date().toISOString()
};
return msg;

var state = flow.get('tsea_state') || {};

msg.payload = {
    ok: true,
    source: 'node_red_local',
    plc: {
        host: '172.24.10.10',
        port: 502,
        model: 'Altus XP325',
        reachable: false
    },
    pumps: {
        pump_b1: state.etapa_atual === 10,
        pump_b2: state.etapa_atual === 20,
        oil_valve: state.etapa_atual === 30
    },
    alarms: {
        alarm_green: state.finalizado === true || state.emergencia_ativa === false,
        alarm_yellow: state.ciclo_ativo === true && state.finalizado === false,
        alarm_red: state.emergencia_ativa === true
    },
    status: {
        ciclo_ativo: state.ciclo_ativo === true,
        finalizado: state.finalizado === true,
        emergencia_ativa: state.emergencia_ativa === true
    },
    registers: {
        etapa_atual: state.etapa_atual || 0,
        codigo_alarme: state.codigo_alarme || 0
    },
    timestamp: new Date().toISOString()
};
return msg;

flow.set('tsea_state', {
    ciclo_ativo: false,
    finalizado: false,
    emergencia_ativa: false,
    etapa_atual: 0,
    codigo_alarme: 0
});
msg.payload = 'OK';
return msg;
